/**
 * What every primitive of audio/ui shares and the kernel does not do: parts
 * named in kebab case, a value reported as `onValueChange` and
 * `onValueCommitted`, one pointer gesture at a time, and a native input
 * hidden from sight. The primitives import it from `../primitive`.
 */
import {
  bindDrag,
  type ChangeSource,
  createChange,
  definePrimitive as definePrimitiveOf,
  dispatch,
  type PointerSample,
  type PrimitiveContext,
} from "@ui-sdk/core";

/** A boolean as a data attribute: present and empty, or absent. */
export const flag = (on: boolean) => (on ? "" : undefined);

/** What a change reports to `onValueChange`, beside the value. */
export interface ChangeDetails {
  cancel: () => void;
  event?: Event;
  /** The point or segment that moved, for a control that has several. */
  index?: number;
  reason: string;
  source?: string;
}

/** What a commit reports to `onValueCommitted`, beside the value. */
export interface CommitDetails {
  event?: Event;
  index?: number;
  reason: string;
}

/** How a native input is hidden while it keeps the focus, the keys and the name. */
export const VISUALLY_HIDDEN = {
  border: "0",
  "clip-path": "inset(50%)",
  height: "1px",
  margin: "-1px",
  overflow: "hidden",
  padding: "0",
  position: "absolute",
  "white-space": "nowrap",
  width: "1px",
};

/**
 * How a change came about, when its event says. The kernel reads it from
 * input it tracks, so the first interaction would report "programmatic"
 * without this. With no event, the kernel decides, and an agent's change
 * stays the agent's.
 */
export function sourceOf(event?: Event): ChangeSource | undefined {
  if (typeof PointerEvent !== "undefined" && event instanceof PointerEvent) {
    return event.pointerType === "touch" || event.pointerType === "pen"
      ? event.pointerType
      : "mouse";
  }
  if (event instanceof MouseEvent) {
    return "mouse";
  }
  if (event instanceof KeyboardEvent) {
    return "keyboard";
  }
}

/** A change or a commit's details: the reason, the event, and who caused it when the event says. */
function detailsOf(reason: string, event?: Event, extra?: object) {
  const source = sourceOf(event);
  return { event, reason, ...(source ? { source } : {}), ...extra };
}

/**
 * How a primitive whose state holds a `value` reports it: `report` fires
 * `onValueChange` and keeps the value unless an app refused it, `commit`
 * fires `onValueCommitted`, and `setAtOnce` does both, for a change that is
 * over as soon as it is made (a key, a typed value, the wheel, a reset). It
 * skips a value `same` finds equal to the one `displayed` shows; with no
 * `same`, every value is reported, even an unchanged one. `extra` goes into
 * the details, such as the `index` of the point that moved.
 */
export function createReporter<State extends { value: Value }, Value>(
  context: PrimitiveContext<any, State, any>,
  displayed: (state: State) => Value,
  same?: (a: Value, b: Value) => boolean
) {
  const change = createChange(context);
  const state = () => context.store.get() as State;
  const commit = (
    value: Value,
    reason: string,
    event?: Event,
    extra?: object
  ) => {
    dispatch(
      context,
      "onValueCommitted",
      value,
      detailsOf(reason, event, extra)
    );
  };
  const report = (
    value: Value,
    reason: string,
    event?: Event,
    extra?: object
  ) =>
    change("value", value as never, detailsOf(reason, event, extra) as never);
  const setAtOnce = (
    value: Value,
    reason: string,
    event?: Event,
    extra?: object
  ) => {
    if (same?.(value, displayed(state()))) {
      return;
    }
    if (report(value, reason, event, extra)) {
      commit(value, reason, event, extra);
    }
  };
  return { commit, report, setAtOnce, state };
}

/** Two numbers as one text: a comma between them, or a semicolon where the comma is the decimal mark. */
export function formatPair(formatter: Intl.NumberFormat, a: number, b: number) {
  const decimalComma = formatter
    .formatToParts(1.5)
    .some((part) => part.type === "decimal" && part.value === ",");
  return `${formatter.format(a)}${decimalComma ? "; " : ", "}${formatter.format(b)}`;
}

/** Where in an interval a curve is checked against its chord, how many times an interval may be halved, and a ceiling on the vertices of one curve. */
const PROBES = [0.25, 0.5, 0.75];
const MAX_DEPTH = 8;
const MAX_SAMPLES = 4096;

/**
 * The vertices of a polyline that draws `f(t)` for `t` from 0 to 1 without
 * straying more than `tolerance` from it: it starts from `grid` and halves
 * every interval whose curve leaves its chord. `width` is how wide `t` from 0
 * to 1 spans in the box the curve is drawn in.
 */
export function adaptiveSamples(
  f: (t: number) => number,
  grid: readonly number[],
  tolerance: number,
  width = 1
) {
  const samples: [number, number][] = [];
  let budget = MAX_SAMPLES - grid.length;
  const refine = (
    from: number,
    start: number,
    to: number,
    end: number,
    depth: number
  ) => {
    if (depth >= MAX_DEPTH || budget <= 0) {
      return;
    }
    let stray = 0;
    let middle = Number.NaN;
    for (const probe of PROBES) {
      const value = f(from + (to - from) * probe);
      stray = Math.max(
        stray,
        Math.abs(value - (start + (end - start) * probe))
      );
      if (probe === 0.5) {
        middle = value;
      }
    }
    const slope = (end - start) / ((to - from) * width);
    if (stray / Math.sqrt(1 + slope * slope) <= tolerance) {
      return;
    }
    const half = (from + to) / 2;
    budget -= 1;
    refine(from, start, half, middle, depth + 1);
    samples.push([half, middle]);
    refine(half, middle, to, end, depth + 1);
  };
  const values = grid.map(f);
  grid.forEach((t, index) => {
    const value = values[index] ?? 0;
    samples.push([t, value]);
    const next = grid[index + 1];
    if (next !== undefined) {
      refine(t, value, next, values[index + 1] ?? 0, 0);
    }
  });
  return samples;
}

/**
 * What a change reports: why it happened (`reason`), the event behind it,
 * and `cancel()` to refuse the change.
 */
export interface ChangeEventDetails<Reason extends string, E extends Event> {
  cancel: () => void;
  event: E;
  readonly isCanceled: boolean;
  reason: Reason;
}

/** What a commit reports once a gesture ends: why it happened and the event behind it. */
export interface CommitEventDetails<Reason extends string, E extends Event> {
  event: E;
  reason: Reason;
}

/** The details of a change for `reason` and `event`, with `cancel()` to refuse it. */
export function createChangeEventDetails<
  Reason extends string,
  E extends Event,
>(reason: Reason, event: E): ChangeEventDetails<Reason, E> {
  let canceled = false;
  return {
    cancel: () => {
      canceled = true;
    },
    event,
    get isCanceled() {
      return canceled;
    },
    reason,
  };
}

/**
 * One pointer at a time on a control: while one drags, a press from another is
 * ignored, and the same pointer pressing again means its release was missed,
 * so the drag it left ends there. Moves arrive at most once per frame, each
 * with where the pointer was at the last one.
 */
export function createPointerLock() {
  type Held = {
    end: (event: PointerEvent) => void;
    pointerId: number;
    stop: () => void;
  };
  let held: Held | null = null;
  return {
    claim: (event: PointerEvent) => {
      if (!held) {
        return true;
      }
      if (held.pointerId !== event.pointerId) {
        return false;
      }
      const stale = held;
      held = null;
      stale.stop();
      stale.end(event);
      return true;
    },
    follow: (
      target: Element,
      down: PointerEvent,
      move: (event: PointerEvent, from: { x: number; y: number }) => void,
      end: (event: PointerEvent) => void
    ) => {
      let last = { x: down.clientX, y: down.clientY };
      const entry: Held = {
        end,
        pointerId: down.pointerId,
        stop: () => undefined,
      };
      held = entry;
      entry.stop = bindDrag(target as HTMLElement, down, {
        onEnd: (event) => {
          if (held === entry) {
            held = null;
          }
          end(event);
        },
        onMove: ({ event }) => {
          const from = last;
          last = { x: event.clientX, y: event.clientY };
          move(event, from);
        },
      });
    },
  };
}

/**
 * A value that changes outside the framework, in the shape of an external
 * store: `subscribe` registers a listener called on each change, and
 * `getSnapshot` returns the current value. What a primitive's `source` reads
 * from, so that following a signal costs no render.
 */
export interface Source<Value> {
  getSnapshot: () => Value;
  subscribe: (listener: () => void) => () => void;
}

/** A source that also takes values: what `createSource` returns. */
export interface WritableSource<Value> extends Source<Value> {
  /** Publishes a value. Subscribers are told every time, so the same array, updated in place, can be published again. */
  set: (value: Value) => void;
}

/**
 * A source you push to yourself, from an audio callback, a WebSocket, a worker
 * or a test: call `set` with each new reading, and whatever reads the source
 * follows.
 */
export function createSource<Value>(initial: Value): WritableSource<Value> {
  let value = initial;
  const listeners = new Set<() => void>();
  return {
    getSnapshot: () => value,
    set: (next) => {
      value = next;
      for (const listener of listeners) {
        listener();
      }
    },
    subscribe: (listener) => {
      listeners.add(listener);
      return () => {
        listeners.delete(listener);
      };
    },
  };
}

/** A value the primitive holds and its parts read outside any render. */
export interface Store<Value> {
  get: () => Value;
  set: (next: Value) => void;
  subscribe: (listener: () => void) => () => void;
}

/** A store holding `initial`: `set` tells every listener, unless the value is the same one. */
export function createStore<Value>(initial: Value): Store<Value> {
  let value = initial;
  const listeners = new Set<() => void>();
  return {
    get: () => value,
    set: (next) => {
      if (Object.is(next, value)) {
        return;
      }
      value = next;
      for (const listener of listeners) {
        listener();
      }
    },
    subscribe: (listener) => {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
  };
}

/** What a gesture hears, from the press that started it to its release. */
export interface GestureHandlers<Data> {
  /** The pointer lifted, or the browser took it over (`canceled`). */
  onEnd: (event: PointerEvent, data: Data, canceled: boolean) => void;
  /** At most once per frame, with the latest pointer event. */
  onMove: (event: PointerEvent, data: Data, sample: PointerSample) => void;
}

/**
 * A primitive's pointer gestures, one at a time. Call `accepts` first, before
 * the primitive's own guards: another pointer pressing while a gesture runs
 * is refused, so a second finger does not take the gesture over, and the
 * same pointer pressing again means its release was missed, so its gesture
 * ends there, through `onStale`. A gesture carries `data` of its own, read
 * back by `active`, and stops when the primitive is destroyed.
 */
export function createGestures<Data>(context: {
  onDestroy: (cleanup: () => void) => void;
}) {
  type Running = { data: Data; pointerId: number; stop: () => void };
  let running: Running | null = null;
  context.onDestroy(() => running?.stop());
  return {
    /** Whether `event` may start a gesture, ending a stale one of the same pointer first. */
    accepts(event: PointerEvent, onStale?: (data: Data) => void) {
      const stale = running;
      if (!stale) {
        return true;
      }
      if (stale.pointerId !== event.pointerId) {
        return false;
      }
      running = null;
      stale.stop();
      onStale?.(stale.data);
      return true;
    },
    /** The data of the gesture that runs, if any. */
    active: () => running?.data ?? null,
    /** Follows the press on `el` until it lifts. */
    start(
      el: HTMLElement,
      event: PointerEvent,
      data: Data,
      handlers: GestureHandlers<Data>
    ) {
      running?.stop();
      const entry: Running = {
        data,
        pointerId: event.pointerId,
        stop: () => undefined,
      };
      running = entry;
      entry.stop = bindDrag(el, event, {
        onEnd: (end, canceled) => {
          if (running === entry) {
            running = null;
          }
          handlers.onEnd(end, data, canceled);
        },
        onMove: (sample) => handlers.onMove(sample.event, data, sample),
      });
    },
  };
}

const KEBAB = /([a-z0-9])([A-Z])/g;
const kebab = (name: string) => name.replace(KEBAB, "$1-$2").toLowerCase();

/**
 * The part a primitive draws names itself in `data-slot`, in kebab case
 * (`xypad-input-x`, `piano-roll-note`), the names the styles and the docs
 * select: the kernel writes the slot's key as it is (`xypad-inputX`). A
 * component that gives its own name to a part (`timeline-time-selection`)
 * keeps it.
 */
function nameSlots(name: string, slots: Record<string, any>) {
  const prefix = kebab(name);
  for (const [key, definition] of Object.entries(slots)) {
    const fallback = key === "root" ? prefix : `${prefix}-${kebab(key)}`;
    const { attrs } = definition;
    definition.attrs = (state: unknown, context: { props?: object }) => ({
      ...attrs?.(state, context),
      "data-slot":
        (context.props as Record<string, string> | undefined)?.["data-slot"] ??
        fallback,
    });
    definition.props = { ...definition.props, "data-slot": "string" };
  }
  return slots;
}

/** `definePrimitive` of the kernel, with the parts named in kebab case and a `data-slot` that can be given. */
export const definePrimitive = ((options: any) =>
  definePrimitiveOf({
    ...options,
    slots: (slot: unknown) => nameSlots(options.name, options.slots(slot)),
  })) as typeof definePrimitiveOf;

import {
  css,
  type PrimitiveInstance,
  type PropSpec,
  type SlotDefinition,
} from "@ui-sdk/core";
import {
  clamp,
  fractionOf,
  scrubTo,
  stepBy,
  stepFromKey,
  numberFormatter,
} from "@ui-sdk/core/number";
import {
  type ChangeDetails,
  type CommitDetails,
  createGestures,
  createReporter,
  definePrimitive,
  flag,
  VISUALLY_HIDDEN,
} from "../primitive";

export type { ChangeDetails, CommitDetails } from "../primitive";

/** Which way a fader's travel runs. */
export type FaderOrientation = "horizontal" | "vertical";

/** The bottom of a fader's range unless given: -60, as for a level in dB. */
export const DEFAULT_MIN = -60;
/** The top of a fader's range unless given: 6. */
export const DEFAULT_MAX = 6;
/** A wheel movement smaller than this is ignored. */
const WHEEL_DELTA_EPSILON = 0.1;

export interface FaderPrimitiveOptions {
  /** Value the fill starts from, such as `0` on a -1 to 1 pan. Defaults to `min`. */
  anchor?: number;
  /** Uncontrolled starting value, and what a reset returns to; defaults to the midpoint. */
  defaultValue?: number;
  disabled?: boolean;
  /** How the value is written, e.g. `{ maximumFractionDigits: 1 }`. */
  format?: Intl.NumberFormatOptions;
  /** Step for Page Up, Page Down and Shift with the arrow keys. @default 10 */
  largeStep?: number;
  locale?: Intl.LocalesArgument;
  /** @default 6 */
  max?: number;
  /** @default -60 */
  min?: number;
  /** The form field's name, which the native input carries. */
  name?: string;
  onValueChange?: (value: number, details: ChangeDetails) => void;
  onValueCommitted?: (value: number, details: CommitDetails) => void;
  /** @default "vertical" */
  orientation?: FaderOrientation;
  /** @default 1 */
  step?: number;
  /** The controlled value; leave it out for the fader to hold its own. */
  value?: number;
}

export interface FaderState {
  anchor: number | undefined;
  defaultValue: number | undefined;
  disabled: boolean;
  /** Where a drag has taken the value, held until release so a controlled value that lags cannot pull the thumb back. */
  draft: number | null;
  dragging: boolean;
  format: Intl.NumberFormatOptions | undefined;
  /** Whether a label part names the fader. */
  labelled: boolean;
  largeStep: number;
  locale: Intl.LocalesArgument | undefined;
  max: number;
  min: number;
  name: string | undefined;
  orientation: FaderOrientation;
  step: number;
  /** The value the app holds, or the fader's own. */
  value: number;
}

/** What a view draws a fader from. */
export interface FaderSnapshot {
  anchor: number | undefined;
  disabled: boolean;
  dragging: boolean;
  /** The fill, from and to, as percentages of the travel. */
  fill: { from: number; to: number };
  /** The value as text, with `format` and `locale`. */
  formatted: string;
  largeStep: number;
  max: number;
  min: number;
  orientation: FaderOrientation;
  /** The thumb's place along the travel, as a percentage. */
  share: number;
  step: number;
  /** The value as displayed: the dragged one while a pointer holds the thumb. */
  value: number;
}

const range = (state: FaderState) => ({
  largeStep: state.largeStep,
  max: state.max,
  min: state.min,
  step: state.step,
});

/** The share of the travel `value` sits at, 0 to 100. */
const shareOf = (state: FaderState, value: number) =>
  fractionOf(value, state) * 100;

const resetValue = (state: FaderState) =>
  state.defaultValue ?? state.min + (state.max - state.min) / 2;

const onGrid = (state: FaderState, raw: number) =>
  scrubTo(raw, range(state)).value;

const displayed = (state: FaderState) =>
  state.draft ?? clamp(state.value, state.min, state.max);

const views = new WeakMap<FaderState, FaderSnapshot>();

/** What the parts draw from `state`, worked out once per state. */
export function viewOf(state: FaderState): FaderSnapshot {
  const cached = views.get(state);
  if (cached) {
    return cached;
  }
  const value = displayed(state);
  const anchor = state.anchor ?? state.min;
  const view: FaderSnapshot = {
    anchor: state.anchor,
    disabled: state.disabled,
    dragging: state.dragging,
    fill: {
      from: shareOf(state, Math.min(anchor, value)),
      to: shareOf(state, Math.max(anchor, value)),
    },
    formatted: numberFormatter(
      state.locale as string | undefined,
      state.format
    ).format(value),
    largeStep: state.largeStep,
    max: state.max,
    min: state.min,
    orientation: state.orientation,
    share: shareOf(state, value),
    step: state.step,
    value,
  };
  views.set(state, view);
  return view;
}

/** Whether `element` lays out right to left, which reverses a horizontal travel. */
function isRtl(element: Element) {
  const view = element.ownerDocument?.defaultView;
  return view ? view.getComputedStyle(element).direction === "rtl" : false;
}

/** The value under a point of the control, on the grid. */
function valueUnder(
  state: FaderState,
  control: HTMLElement,
  x: number,
  y: number
) {
  const box = control.getBoundingClientRect();
  const vertical = state.orientation === "vertical";
  let share = vertical
    ? (box.bottom - y) / (box.height || 1)
    : (x - box.left) / (box.width || 1);
  if (!vertical && isRtl(control)) {
    share = 1 - share;
  }
  return onGrid(
    state,
    state.min + clamp(share, 0, 1) * (state.max - state.min)
  );
}

/** What the parts of a fader read: its state, drawn. */
export interface FaderPublicState {
  disabled: boolean;
  dragging: boolean;
  formatted: string;
  max: number;
  min: number;
  orientation: FaderOrientation;
  value: number;
}

const publicState = (state: FaderState): FaderPublicState => {
  const view = viewOf(state);
  return {
    disabled: view.disabled,
    dragging: view.dragging,
    formatted: view.formatted,
    max: view.max,
    min: view.min,
    orientation: view.orientation,
    value: view.value,
  };
};

/** The state attributes every part carries. */
const stateAttrs = (state: FaderState) => ({
  "data-disabled": flag(state.disabled),
  "data-dragging": flag(state.dragging),
  "data-orientation": state.orientation,
});

/** What a fader's `api` gives an adapter. */
export interface FaderApi {
  /** Handles a key on the fader's input: arrows, Page Up and Down, Home and End. Returns whether the fader took the key. */
  keyDown: (event: KeyboardEvent, element: Element) => boolean;
  /** Starts a pointer gesture on the control: a press on the track jumps to the value under it, a press on the thumb drags from where it was taken. */
  press: (
    event: PointerEvent,
    control: HTMLElement,
    thumb: HTMLElement | null
  ) => void;
  /** Returns to the default value, reporting a `"reset"` change and commit. */
  reset: (event?: Event) => void;
  /** Moves the fader to `value` from outside, as a property does: no change is reported. */
  set: (value: number) => void;
  /** Sets the value as typed: on the grid, reported and committed. */
  setValue: (value: number, event?: Event) => void;
  /** The value as displayed. */
  value: () => number;
  /** Listens to wheel steps on `element`; returns what removes the listener. */
  wheel: (element: HTMLElement) => () => void;
}

/** The props every part takes. */
interface PartProps {
  id?: string;
}

/** The fader's slots, by name, with the props and the public state of each. */
export type FaderSlots = {
  control: SlotDefinition<FaderState, FaderApi, PartProps, FaderPublicState>;
  indicator: SlotDefinition<FaderState, FaderApi, PartProps, FaderPublicState>;
  input: SlotDefinition<
    FaderState,
    FaderApi,
    PartProps & {
      getAriaValueText?: (
        formatted: string,
        value: number,
        index: number
      ) => string;
    },
    object
  >;
  label: SlotDefinition<FaderState, FaderApi, PartProps, object>;
  mark: SlotDefinition<
    FaderState,
    FaderApi,
    PartProps & { value: number },
    FaderPublicState & { active: boolean }
  >;
  root: SlotDefinition<FaderState, FaderApi, PartProps, FaderPublicState>;
  thumb: SlotDefinition<FaderState, FaderApi, PartProps, FaderPublicState>;
  track: SlotDefinition<FaderState, FaderApi, PartProps, FaderPublicState>;
  value: SlotDefinition<FaderState, FaderApi, PartProps, FaderPublicState>;
};

/**
 * The type of `fader`, written out: the kernel's own types its inferred type
 * would name are not exported, so a declaration could not print it.
 */
export interface FaderPrimitive {
  options: Record<string, PropSpec> | undefined;
  slots: FaderSlots;
  (
    initialOptions: FaderPrimitiveOptions & { id: string }
  ): Omit<PrimitiveInstance, "api" | "get" | "types"> & {
    api: FaderApi;
    get: () => FaderState;
    types: {
      api: FaderApi;
      options: FaderPrimitiveOptions;
      slots: FaderSlots;
      state: FaderState;
    };
  };
}

const inputOf = (el: HTMLElement | undefined) =>
  el?.querySelector<HTMLInputElement>('input[type="range"]') ?? undefined;

/** The state an options object asks for, with the defaults of the fader. */
function stateOf(options: FaderPrimitiveOptions) {
  return {
    anchor: options.anchor,
    defaultValue: options.defaultValue,
    disabled: options.disabled ?? false,
    format: options.format,
    largeStep: options.largeStep ?? 10,
    locale: options.locale,
    max: options.max ?? DEFAULT_MAX,
    min: options.min ?? DEFAULT_MIN,
    name: options.name,
    orientation: options.orientation ?? "vertical",
    step: options.step ?? 1,
  } satisfies Partial<FaderState>;
}

export const fader: FaderPrimitive = definePrimitive({
  agent: { actions: ["setValue"] },
  api: (context) => {
    const { commit, report, setAtOnce, state } = createReporter(
      context,
      displayed,
      Object.is
    );
    const gestures = createGestures(context);

    return {
      keyDown: (event: KeyboardEvent, element: Element) => {
        const current = state();
        if (current.disabled) {
          return false;
        }
        const move = stepFromKey(event, {
          dir: isRtl(element) ? "rtl" : "ltr",
          orientation: current.orientation,
        });
        if (!move) {
          return false;
        }
        const next = stepBy(displayed(current), move, range(current));
        setAtOnce(onGrid(current, next), "keyboard", event);
        return true;
      },
      press: (
        event: PointerEvent,
        control: HTMLElement,
        thumb: HTMLElement | null
      ) => {
        if (
          state().disabled ||
          event.button !== 0 ||
          !gestures.accepts(event, () =>
            context.store.set({ dragging: false, draft: null } as never)
          )
        ) {
          return;
        }
        const current = state();
        const vertical = current.orientation === "vertical";
        const onThumb = Boolean(thumb?.contains(event.target as Node));
        // Taken by the thumb, the drag keeps the pointer where it grabbed it.
        let offset = 0;
        if (thumb && onThumb) {
          const box = thumb.getBoundingClientRect();
          offset = vertical
            ? event.clientY - (box.top + box.height / 2)
            : event.clientX - (box.left + box.width / 2);
        }
        let value = displayed(current);
        // Whether the gesture set a value, even one it later came back from.
        let changed = false;
        let moved = false;
        const set = (next: number, reason: string, source: Event) => {
          if (next !== value && report(next, reason, source)) {
            value = next;
            changed = true;
            context.store.set({ draft: next } as never);
          }
        };
        if (!onThumb) {
          set(
            valueUnder(current, control, event.clientX, event.clientY),
            "track-press",
            event
          );
        }
        context.store.set({ dragging: true } as never);
        gestures.start(control, event, null, {
          onEnd: (end) => {
            context.store.set({ dragging: false, draft: null } as never);
            if (changed) {
              commit(value, moved ? "drag" : "track-press", end);
            }
          },
          onMove: (move) => {
            moved = true;
            set(
              valueUnder(
                state(),
                control,
                move.clientX - (vertical ? 0 : offset),
                move.clientY - (vertical ? offset : 0)
              ),
              "drag",
              move
            );
          },
        });
      },
      reset: (event?: Event) => {
        const current = state();
        if (current.disabled) {
          return;
        }
        setAtOnce(
          clamp(resetValue(current), current.min, current.max),
          "reset",
          event ?? new Event("reset")
        );
      },
      set: (value: number) => context.store.set({ value } as never),
      setValue: (value: number, event?: Event) =>
        setAtOnce(
          onGrid(state(), value),
          "input-change",
          event ?? new Event("change")
        ),
      value: () => displayed(state()),
      wheel: (element: HTMLElement) => {
        const handle = (event: WheelEvent) => {
          const current = state();
          if (current.disabled || event.ctrlKey || event.metaKey) {
            return;
          }
          event.preventDefault();
          if (Math.abs(event.deltaY) < WHEEL_DELTA_EPSILON) {
            return;
          }
          const next = stepBy(
            displayed(current),
            { direction: event.deltaY < 0 ? 1 : -1, size: "step" },
            range(current)
          );
          setAtOnce(onGrid(current, next), "wheel", event);
        };
        const listening = new AbortController();
        element.addEventListener("wheel", handle, {
          passive: false,
          signal: listening.signal,
        });
        return () => listening.abort();
      },
    };
  },
  controlled: ["value"],
  name: "fader",
  options: {
    anchor: "number",
    defaultValue: "number",
    disabled: "boolean",
    format: "value",
    largeStep: "number",
    locale: "value",
    max: "number",
    min: "number",
    name: "string",
    onValueChange: "callback",
    onValueCommitted: "callback",
    orientation: "string",
    step: "number",
    value: "number",
  },
  slots: (slot) => ({
    control: slot<object, FaderPublicState>({
      attrs: (state: FaderState) => ({
        ...stateAttrs(state),
        style: css({ position: "relative", "touch-action": "none" }),
      }),
      bind: (el, part) => part.api.wheel(el),
      on: {
        // A double click, an Alt + click or Delete return to the default, as in a DAW.
        dblclick: (event, { api, el }) => {
          if (el) {
            api.reset(event);
          }
        },
        keydown: (event, { api }) => {
          if (event.key === "Delete" || event.key === "Backspace") {
            event.preventDefault();
            api.reset(event);
          }
        },
        pointerdown: (event, { api, el }) => {
          if (!el || event.button !== 0) {
            return;
          }
          event.preventDefault();
          if (event.altKey) {
            api.reset(event);
            return;
          }
          inputOf(el)?.focus({ preventScroll: true });
          api.press(
            event,
            el,
            el.querySelector<HTMLElement>('[data-slot="fader-thumb"]')
          );
        },
      },
      state: (state: FaderState) => publicState(state),
    }),
    indicator: slot<object, FaderPublicState>({
      attrs: (state: FaderState) => {
        const { fill } = viewOf(state);
        const size = fill.to - fill.from;
        return {
          ...stateAttrs(state),
          style: css(
            state.orientation === "vertical"
              ? {
                  bottom: `${fill.from}%`,
                  height: `${size}%`,
                  width: "inherit",
                }
              : {
                  height: "inherit",
                  "inset-inline-start": `${fill.from}%`,
                  width: `${size}%`,
                }
          ),
        };
      },
      state: (state: FaderState) => publicState(state),
    }),
    // The native range input: the role, the value and the name live on it.
    input: slot<{
      getAriaValueText?: (
        formatted: string,
        value: number,
        index: number
      ) => string;
    }>({
      attrs: (state: FaderState, { id, props }) => {
        const view = viewOf(state);
        return {
          "aria-labelledby": state.labelled ? `${id}-label` : undefined,
          "aria-orientation": state.orientation,
          "aria-valuetext": props.getAriaValueText
            ? props.getAriaValueText(view.formatted, view.value, 0)
            : view.formatted,
          disabled: flag(state.disabled),
          max: String(state.max),
          min: String(state.min),
          name: state.name,
          step: String(state.step),
          style: css({
            ...VISUALLY_HIDDEN,
            height: "100%",
            width: "100%",
            ...(state.orientation === "vertical"
              ? { "writing-mode": "vertical-lr" }
              : {}),
          }),
          type: "range",
          value: String(view.value),
        };
      },
      on: {
        change: (event, { api, el }) =>
          api.setValue(Number((el as HTMLInputElement).value), event),
        input: (event, { api, el }) =>
          api.setValue(Number((el as HTMLInputElement).value), event),
        keydown: (event, { api, el }) => {
          if (el && api.keyDown(event, el)) {
            event.preventDefault();
          }
        },
      },
      props: { getAriaValueText: "value" },
    }),
    label: slot({
      attrs: (state: FaderState, { id }) => ({
        ...stateAttrs(state),
        id: `${id}-label`,
      }),
      bind: (_el, part) => {
        part.store.set({ labelled: true });
        return () => part.store.set({ labelled: false });
      },
    }),
    mark: slot<{ value: number }, FaderPublicState & { active: boolean }>({
      attrs: (state: FaderState, { props }) => {
        const at = shareOf(state, props.value);
        const { anchor, min, value } = viewOf(state);
        const from = anchor ?? min;
        const active =
          props.value >= Math.min(from, value) &&
          props.value <= Math.max(from, value);
        return {
          "aria-hidden": "true",
          "data-active": flag(active),
          "data-disabled": flag(state.disabled),
          "data-orientation": state.orientation,
          style: css({
            position: "absolute",
            ...(state.orientation === "vertical"
              ? { bottom: `${at}%` }
              : { "inset-inline-start": `${at}%` }),
          }),
        };
      },
      props: { value: "number" },
      state: (state: FaderState, { props }) => {
        const { anchor, min, value } = viewOf(state);
        const from = anchor ?? min;
        return {
          ...publicState(state),
          active:
            props.value >= Math.min(from, value) &&
            props.value <= Math.max(from, value),
        };
      },
    }),
    root: slot<object, FaderPublicState>({
      attrs: (state: FaderState, { id }) => ({
        ...stateAttrs(state),
        "aria-labelledby": state.labelled ? `${id}-label` : undefined,
        role: "group",
      }),
      state: (state: FaderState) => publicState(state),
    }),
    thumb: slot<object, FaderPublicState>({
      attrs: (state: FaderState) => {
        const { share } = viewOf(state);
        const vertical = state.orientation === "vertical";
        return {
          ...stateAttrs(state),
          style: css({
            ...(vertical
              ? { bottom: `${share}%`, left: "50%", translate: "-50% 50%" }
              : {
                  "inset-inline-start": `${share}%`,
                  top: "50%",
                  translate: "-50% -50%",
                }),
            position: "absolute",
            ...(state.dragging ? { "z-index": "1" } : {}),
          }),
        };
      },
      state: (state: FaderState) => publicState(state),
    }),
    track: slot<object, FaderPublicState>({
      attrs: (state: FaderState) => ({
        ...stateAttrs(state),
        style: css({ position: "relative" }),
      }),
      state: (state: FaderState) => publicState(state),
    }),
    value: slot<object, FaderPublicState>({
      attrs: (state: FaderState) => ({
        ...stateAttrs(state),
        "aria-live": "off",
      }),
      state: (state: FaderState) => publicState(state),
    }),
  }),
  state: (options: FaderPrimitiveOptions): FaderState => {
    const base = {
      ...stateOf(options),
      draft: null,
      dragging: false,
      labelled: false,
      value: 0,
    } satisfies FaderState;
    return {
      ...base,
      value: options.value ?? options.defaultValue ?? resetValue(base),
    };
  },
  sync: (options: FaderPrimitiveOptions) =>
    options.value === undefined
      ? stateOf(options)
      : { ...stateOf(options), value: options.value },
});

import { type FaderPublicState, fader } from "./fader";
import { createParts } from "@ui-sdk/vue/primitive";
import { defineComponent, h } from "vue";

/** Which element each part is. */
const parts = createParts(fader, {
  control: "div",
  indicator: "div",
  input: "input",
  label: "div",
  mark: "div",
  root: "div",
  thumb: "div",
  track: "div",
  value: "output",
});

/** The thumb, with the native input that carries the fader's name inside it. */
const Thumb = defineComponent(
  (
    props: {
      getAriaValueText?: (
        formatted: string,
        value: number,
        index: number
      ) => string;
    },
    { attrs, slots }
  ) =>
    () => {
      const { "aria-label": label, ...rest } = attrs;
      return h(parts.Thumb, rest, {
        default: (scope: { state: FaderPublicState }) => [
          slots.default?.(scope),
          h(parts.Input, {
            "aria-label": label as string | undefined,
            getAriaValueText: props.getAriaValueText,
          }),
        ],
      });
    },
  { inheritAttrs: false, name: "FaderThumb", props: ["getAriaValueText"] }
);

const Value = defineComponent(
  (_props, { attrs, slots }) =>
    () =>
      h(parts.Value, attrs, {
        default:
          slots.default ??
          (({ state }: { state: FaderPublicState }) => state.formatted),
      }),
  { inheritAttrs: false, name: "FaderValue" }
);

export const Fader = {
  Control: parts.Control,
  Indicator: parts.Indicator,
  Label: parts.Label,
  Mark: parts.Mark,
  Root: parts.Root,
  Thumb,
  Track: parts.Track,
  Value,
};
